 async function duplicateContent(item,destination,name,overrides={}){guard();const next=clone(draft),sourceId=item.id;item=clone(item);item.id=uid('block');item.title=name||item.title;arrayFor('blocks',next,'',destination).push(item);for(const[key,value]of Object.entries(overrides)){const copied=clone(value);if(copied.positions){for(const[profile,position]of Object.entries(copied.positions)){if(position.container.includes('block-'+sourceId))position.container=position.container.replace(/^page-[^:]+:/,'page-'+destination+':').replace('block-'+sourceId,'block-'+item.id);else delete copied.positions[profile];}}delete copied.placement;delete copied.locked;delete copied.removed;next.elementOverrides||={};next.elementOverrides[key.replace(/^page-[^:]+:/,'page-'+destination+':').replace('block-'+sourceId,'block-'+item.id)]=copied;}await apply(next);announce('Copia creada en '+(next.navigation.find(nav=>nav.id===destination)?.label||destination)+'.');}
 async function duplicateSection(id,snapshot){guard();const next=clone(draft),original=next.pages.find(page=>page.id===id),nav=next.navigation.find(item=>item.id===id);if(!nav)return;const page=original?clone(original):{title:nav.label,eyebrow:'',description:'',layout:'list',blocks:snapshot?[{id:uid('block'),type:'group',title:nav.label,snapshot,slides:[]}]:clone(next.sectionBlocks[id]||[])};page.id=uid('section');page.title+=' (copia)';const mapping=new Map();for(const block of page.blocks){const old=block.id;block.id=uid('block');mapping.set(old,block.id);}next.pages.push(page);next.navigation.push({id:page.id,label:page.title,icon:nav.icon||'none',visible:true});for(const[key,value]of Object.entries(next.elementOverrides||{}))if(key.startsWith('page-'+id+':')&&original){let newKey=key.replace('page-'+id+':','page-'+page.id+':');for(const[old,fresh]of mapping)newKey=newKey.replace('block-'+old,'block-'+fresh);const copied=clone(value);delete copied.positions;delete copied.placement;delete copied.locked;next.elementOverrides[newKey]=copied;}await apply(next);announce('Sección duplicada. Encuéntrala en la navegación.');}
