  if(panel==='menus')return `<p class="subtle">Cambia los nombres, iconos y el orden de la navegación. Crea secciones con sus propios bloques y botones.</p><h3>Navegación</h3><button class="button secondary" data-cms-center-navigation>Centrar navegación</button>${listRows('navigation',draft.navigation,'label')}<div class="panel-actions">${addButton('pages','Crear menú o sección')}</div>${["noticias","recetario","libro","comparte"].filter(id=>draft.navigation.some(item=>item.id===id)).map(id=>`<section class="cms-page"><h3>${esc(draft.navigation.find(item=>item.id===id)?.label || id)}</h3>${listRows("blocks",sectionBlocks(draft,id),"title")}<button class="button secondary" data-cms-add-menu="${id}">+ Agregar</button></section>`).join("")}${draft.pages.map(page=>`<section class="cms-page"><div class="cms-row"><strong>${esc(page.title)}</strong><div class="cms-row-actions"><button class="button secondary" data-edit-panel="pages" data-edit-id="${page.id}">Editar sección</button><button class="icon-button" data-cms-delete="pages" data-id="${page.id}" aria-label="Eliminar ${esc(page.title)}">✕</button></div></div>${listRows('blocks',page.blocks,'title')}<button class="button secondary" data-cms-add="blocks" data-page="${page.id}">+ Añadir bloque a ${esc(page.title)}</button></section>`).join('')}`;
