 return {
  get isAdmin(){return service.isAdmin;},get dirty(){return dirty;},get configured(){return service.configured;},
  adminMarkup,accountMarkup,editContent:openEditor,applyDocument:apply,removeElement:requestRemoval,duplicateContent,duplicateSection,
  resetLayout(){return apply(clone(published));},
  editElement(key,defaults,tag,group,bindings={}){guard();const item={headerMode:draft.brand.titleMode||'text',...defaults,...draft.elementOverrides?.[key]};for(const token of ['@table','@chef','@brand'])if(item.image===imageURL(token))item.image=token;openEditor('element',key,item);editorState.bindings=bindings;drawer.querySelector('[name="headerMode"]').closest('.cms-field').hidden=bindings.image!=='brand.logo';if(group||tag==='IMG')drawer.querySelector('[name="text"]').closest('.cms-field').hidden=true;for(const name of (tag==='IMG'?['link','icon','size']:tag!=='A'&&!bindings.link?['link']:[]))drawer.querySelector(`[name="${name}"]`).closest('.cms-field').hidden=true;},
  toolsMarkup(){return service.isAdmin?`<button class="button editor-toggle" data-layout-toggle aria-pressed="false" aria-label="Editar todos los elementos">✎ Editar</button><span class="editor-status">${!draftPersisted?'Borrador en esta visita: exporta una copia':dirty?'Borrador sin publicar':'Edición de administrador'}</span><a href="#noticias" class="button secondary">Vista previa</a><button class="button" data-cms-publish ${dirty?'':'disabled'}>Publicar</button><details class="editor-more"><summary class="button secondary" aria-label="Más opciones de administración">Más</summary><div class="editor-more-menu"><a href="#admin" class="button secondary">Panel de administración</a><button class="button secondary" data-layout-reset-all>Restaurar acomodo original</button><button class="button secondary" data-cms-reset-site>Restaurar diseño inicial</button></div></details>`:'';},
  addMarkup(section,{recipeMenu=''}={}){if(section==='empty')return service.isAdmin?'<div class="section-admin-toolbar"><button class="button" data-new-element="menu" data-section="empty">+ Crear sección</button></div>':'';return service.isAdmin?`<div class="section-admin-toolbar"><span>Editar esta sección</span><button class="button secondary" data-cms-compact>Ajustar espacios</button><div class="panel-actions">${section==='recetario'?`<button class="button" data-cms-add="recipes" data-menu-context="${esc(recipeMenu)}">+ Agregar platillo</button>`:''}${section==='recetario'?`<button class="button secondary" data-category-manage>Categorías</button>`:''}${section==='novedades'?`<button class="button" data-cms-add="news">+ Agregar nota</button>`:''}${draft.navigation.some(item=>item.id===section)?`<button class="button secondary" data-layout-duplicate-section="${section}">Duplicar sección</button><button class="button secondary" data-cms-delete="navigation" data-id="${section}">Eliminar sección</button>`:''}<button class="button secondary" data-cms-add-menu="${section}" data-recipe-context="${esc(recipeMenu)}">+ Agregar</button></div></div>`:'';},
  accountTools(){return service.user?`<a href="#${service.isAdmin?'admin':'cuenta'}">${service.isAdmin?'Administrar':'Mi cuenta'}</a><button data-account-logout>Cerrar sesión</button>`:'<a href="#cuenta">Iniciar sesión</a><a href="#registro">Registro</a>';},
  async initialize(){if(!service.configured)return;const results=await Promise.allSettled([service.published(),service.restore()]);if(results[0].status==='fulfilled'){const latest=results[0].value;if(latest.document){published=createSiteDocument(latest.document);validateSiteDocument(published);draft=clone(published);}revision=latest.revision;baseRevision=revision;}else connectionIssue='No pudimos actualizar el contenido. Puedes volver a intentarlo.';if(results[1].status==='rejected')connectionIssue='No pudimos recuperar tu sesión. Inicia sesión de nuevo.';accountNotice=service.authIssue||service.authNotice||accountNotice;onPreview(clone(published));await restoreDraft();},
  setPanel(value){if(panels.some(x=>x[0]===value))panel=value;}
 };
